def _workflow(name: str, mode: str, body: str = "") -> str:
    extra = f"\n{body.rstrip()}\n" if body else "\n"
    return f"""name: {name}

on:
  push:
  workflow_dispatch:

permissions:
  contents: read

jobs:{extra}"""


def _standard_job(mode: str, *, setup_python: bool = False) -> str:
    python_step = ""
    if setup_python:
        python_step = f"""      - name: Set up Python
        uses: actions/setup-python@{SETUP_PYTHON_SHA}
        with:
          python-version: "3.10"
"""
    return f"""  {mode}:
    runs-on: ubuntu-latest
    timeout-minutes: 120
    steps:
      - name: Check out mirror
        uses: actions/checkout@{CHECKOUT_SHA}
        with:
          persist-credentials: false
      - name: Set up Bazel
        uses: ./.github/actions/setup-aorta-bazel
{python_step}      - name: Run {mode}
        run: python3 .github/scripts/mirror_ci.py {mode}
"""


def _workflows() -> dict[str, str]:
    workflows = {
        "mirror-build-test.yml": _workflow(
            "Mirror build and test", "build-test", _standard_job("build-test")
        ),
        "mirror-lint.yml": _workflow("Mirror lint", "lint", _standard_job("lint")),
        "mirror-python-sdk.yml": _workflow(
            "Mirror Python SDK",
            "python-sdk",
            _standard_job("python-sdk", setup_python=True),
        ),
        "mirror-schema-integrity.yml": _workflow(
            "Mirror schema integrity",
            "schema-integrity",
            _standard_job("schema-integrity"),
        ),
        "mirror-consumer-smoke.yml": _workflow(
            "Mirror consumer smoke",
            "consumer-smoke",
            _standard_job("consumer-smoke"),
        ),
    }
    workflows["mirror-python-wheels.yml"] = f"""name: Mirror Python wheels

on:
  push:
    tags: ["v*"]
  workflow_dispatch:
    inputs:
      version:
        description: Wheel version
        required: true

permissions:
  contents: read

jobs:
  python-wheels:
    strategy:
      fail-fast: false
      matrix:
        include:
          - id: linux-x86_64
            runner: ubuntu-latest
            include_messages: "true"
          - id: linux-arm64
            runner: ubuntu-24.04-arm
            include_messages: "false"
          - id: macos-arm64
            runner: macos-14
            include_messages: "false"
    runs-on: ${{{{ matrix.runner }}}}
    timeout-minutes: 120
    steps:
      - name: Check out mirror
        uses: actions/checkout@{CHECKOUT_SHA}
        with:
          persist-credentials: false
      - name: Set up Bazel
        uses: ./.github/actions/setup-aorta-bazel
      - name: Build wheels from the mirror
        env:
          INCLUDE_MESSAGES: ${{{{ matrix.include_messages }}}}
          WHEEL_EVENT_NAME: ${{{{ github.event_name }}}}
          WHEEL_REF_NAME: ${{{{ github.ref_name }}}}
          WHEEL_VERSION_INPUT: ${{{{ inputs.version || '' }}}}
        run: >-
          python3 .github/scripts/mirror_ci.py python-wheels
          --include-messages "$INCLUDE_MESSAGES"
          --event-name "$WHEEL_EVENT_NAME"
          --ref-name "$WHEEL_REF_NAME"
          --version-input "$WHEEL_VERSION_INPUT"
      - name: Upload wheels
        uses: actions/upload-artifact@{UPLOAD_ARTIFACT_SHA}
        with:
          name: aorta-wheels-${{{{ matrix.id }}}}
          path: dist/*.whl
          if-no-files-found: error
"""
    return workflows


def generated_files() -> dict[str, tuple[bytes, int]]:
    files = {
        f".github/workflows/{name}": (text.encode("utf-8"), 0o644)
        for name, text in _workflows().items()
    }
    files.update(
        {
            ".github/actionlint.yaml": (b"{}\n", 0o644),
            ".github/actions/setup-aorta-bazel/README.md": (
                b"# Public mirror CI\n\n"
                b"This action installs Bazelisk and the pinned Rust toolchain on GitHub-hosted runners. It does not "
                b"read credentials, configure a remote cache, or access private modules.\n\n"
                b"Local tests cover workflow rendering, action pin policy, script command "
                b"routing, schema inventory checks, and fork-safe secret absence. Native "
                b"runner availability, cold-build duration, arm64 wheel production, and "
                b"GitHub event behavior require runs on GitHub Actions.\n\n"
                b"The initial mirror intentionally excludes sanitizer, tsan-xlang, miri, "
                b"loom, fuzz, benchmark, release, runner maintenance, and long-running "
                b"interop workflows. Their private-runner coverage is not implied by "
                b"the six public workflows.\n",
                0o644,
            ),
            ".github/actions/setup-aorta-bazel/action.yml": (
                f"""name: Set up public Aorta Bazel
description: Install public build tools without private credentials or caches.
runs:
  using: composite
  steps:
    - name: Free hosted Linux disk space
      if: runner.environment == 'github-hosted' && runner.os == 'Linux'
      shell: bash
      run: |
        df -h /
        sudo rm -rf /usr/share/dotnet /usr/local/lib/android /opt/ghc /opt/hostedtoolcache/CodeQL
        df -h /
    - name: Install Bazelisk
      uses: bazelbuild/setup-bazelisk@{SETUP_BAZELISK_SHA}
    - name: Install Linux build dependencies
      if: runner.os == 'Linux'
      shell: bash
      run: |
        sudo apt-get update
        sudo apt-get install -y build-essential clang cmake ninja-build pkg-config
    - name: Verify Bazel
      shell: bash
      run: bazel version
    - name: Set up Rust
      shell: bash
      run: |
        rustup toolchain install {RUST_TOOLCHAIN} --profile minimal --component clippy,rustfmt
        echo "RUSTUP_TOOLCHAIN={RUST_TOOLCHAIN}" >> "$GITHUB_ENV"
""".encode("utf-8"),
                0o644,
            ),
            ".github/scripts/mirror_ci.py": (_generated_script_bytes(), 0o755),
        }
    )
    return files


def _mirror_consumer_files() -> dict[str, str]:
    if _EMBEDDED_CONSUMER_FILES is not None:
        return {
            relative: base64.b64decode(data).decode("utf-8")
            for relative, data in _EMBEDDED_CONSUMER_FILES.items()
        }

    import mirror_gate
    import remote_allowlist
    import validate_source_consumer

    with tempfile.TemporaryDirectory(prefix="aorta-mirror-ci-fixture-") as tmp:
        workspace = Path(tmp) / "consumer"
        validate_source_consumer.prepare_workspace(
            workspace,
            Path(__file__).resolve().parents[2],
            mode=validate_source_consumer.MIRROR_CONSUMER_MODE,
            aorta_remote=_CONSUMER_REMOTE_PLACEHOLDER,
            aorta_commit=_CONSUMER_COMMIT_PLACEHOLDER,
        )
        module_path = workspace / "MODULE.bazel"
        module = module_path.read_text(encoding="utf-8")
        self_override = (
            "git_override(\n"
            '    module_name = "aorta",\n'
            f"    remote = {json.dumps(_CONSUMER_REMOTE_PLACEHOLDER)},\n"
            f"    commit = {json.dumps(_CONSUMER_COMMIT_PLACEHOLDER)},\n"
            ")\n"
        )
        if self_override not in module:
            raise RuntimeError("mirror consumer renderer omitted the self git_override")
        module_path.write_text(module.replace(self_override, "", 1), encoding="utf-8")
        remote_allowlist.validate_tree(workspace)
        module_path.write_text(module, encoding="utf-8")
        scan = mirror_gate.scan_tree(
            workspace,
            Path(__file__).with_name("mirror_scanner_exceptions.json"),
            Path(__file__).with_name("mirror_binary_register.json"),
        )
        if scan["blocking_hits"] or scan["binary_errors"]:
            raise RuntimeError("mirror consumer fixture failed the public leak scan")
        return {
            path.relative_to(workspace).as_posix(): path.read_text(encoding="utf-8")
            for path in sorted(workspace.rglob("*"))
            if path.is_file()
        }


def _generated_script_bytes() -> bytes:
    source = Path(__file__).read_text(encoding="utf-8")
    marker = "_EMBEDDED_CONSUMER_FILES" + " = None"
    encoded = {
        relative: base64.b64encode(data.encode("utf-8")).decode("ascii")
        for relative, data in _mirror_consumer_files().items()
    }
    replacement = "_EMBEDDED_CONSUMER_FILES = " + json.dumps(encoded, sort_keys=True)
    if source.count(marker) != 1:
        raise RuntimeError("mirror CI embedding marker is missing or duplicated")
    return source.replace(marker, replacement, 1).encode("utf-8")


def _run(command: list[str], *, cwd: Path | None = None, env: dict[str, str] | None = None) -> None:
    subprocess.run(command, cwd=cwd, env=env, check=True)


def _run_with_fetch_retry(
    command: list[str],
    *,
    cwd: Path | None = None,
    env: dict[str, str] | None = None,
    runner=subprocess.run,
) -> None:
    """Run a fetch-heavy command, retrying only transient network signatures.

    Bounded to three attempts with a 30s * attempt backoff. A failure whose
    combined output matches TRANSIENT_FETCH_SIGNATURES is retried; every
    other failure raises the runner's CalledProcessError immediately.
    """
    for attempt in range(1, _FETCH_RETRY_ATTEMPTS + 1):
        result = runner(command, cwd=cwd, env=env, capture_output=True, text=True)
        stdout = result.stdout or ""
        stderr = result.stderr or ""
        if stdout:
            print(stdout, end="")
        if stderr:
            print(stderr, end="", file=sys.stderr)
        if result.returncode == 0:
            return
        match = _TRANSIENT_FETCH_RE.search(stdout + stderr)
        if match is None:
            raise subprocess.CalledProcessError(
                result.returncode, command, output=stdout, stderr=stderr
            )
        print(
            f"attempt {attempt}/{_FETCH_RETRY_ATTEMPTS} hit transient fetch "
            f"signature: {match.group(0)}"
        )
        if attempt == _FETCH_RETRY_ATTEMPTS:
            raise subprocess.CalledProcessError(
                result.returncode, command, output=stdout, stderr=stderr
            )
        time.sleep(_FETCH_RETRY_DELAY_SECONDS * attempt)


def _build_test() -> None:
    # Keep assertions and the complete test set; omit duplicated DWARF payloads
    # from Rust archives and discard unused sections in linked C++ tests.
    common = [
        "--lockfile_mode=error",
        "--@rules_rust//rust/settings:extra_rustc_flag=-Cdebuginfo=0",
        "--linkopt=-Wl,--gc-sections",
    ]
    _run_with_fetch_retry(["bazel", "build", *PUBLIC_BAZEL_TARGETS, *common])
    _run_with_fetch_retry(
        [
            "bazel",
            "test",
            "//cpp/...",
            "//rust/...",
            "//message/...",
            "//test/...",
            "--build_tests_only",
            *common,
        ]
    )


# Deferred design/API audits: task ownership, locks across await, error boxing,
# argument grouping, and FFI enum layout. All other Core/SDK warnings block CI.
DEFERRED_CLIPPY_LINTS = (
    "clippy::let_underscore_future",
    "clippy::await_holding_lock",
    "clippy::result_large_err",
    "clippy::too_many_arguments",
    "clippy::large_enum_variant",
)

ADVISORY_CLIPPY_TOOLS = (
    "tools/aorta-cli",
    "tools/aorta-play",
    "tools/aorta-record",
    "tools/aorta-introspect",
    "tools/aorta-tui",
    "tools/zenohd",
    "tools/aorta-trace2perfetto",
)


def _clippy_hard(env: dict[str, str] | None = None) -> None:
    flags = ["-D", "warnings"]
    for lint in DEFERRED_CLIPPY_LINTS:
        flags.extend(["-A", lint])
    for crate, targets in (("core", ["--all-targets"]), ("rust", ["--lib", "--tests"])):
        _run(
            ["cargo", "clippy", *targets, "--all-features", "--", *flags],
            cwd=Path(crate),
            env=env,
        )


def _clippy_tools(env: dict[str, str] | None = None) -> int:
    had_failures = 0
    for crate in ADVISORY_CLIPPY_TOOLS:
        try:
            _run(["cargo", "clippy", "--all-targets", "--all-features"], cwd=Path(crate), env=env)
        except subprocess.CalledProcessError:
            print(f"[clippy] {crate} has lints (advisory only)", flush=True)
            had_failures = 1
    return had_failures


def _lint() -> None:
    _run(["cargo", "fmt", "--all", "--check"])
    _run_with_fetch_retry(["bazel", "build", "@flatbuffers//:flatc", "--lockfile_mode=error"])
    flatc = subprocess.check_output(
        ["bazel", "cquery", "--output=files", "@flatbuffers//:flatc", "--lockfile_mode=error"],
        text=True,
    ).strip()
    output_base = subprocess.check_output(["bazel", "info", "output_base"], text=True).strip()
    env = os.environ.copy()
    env["FLATC"] = str(Path.cwd() / flatc)
    env["AORTA_FLATBUFFERS_ROOT"] = str(Path(output_base) / "external/flatbuffers~")
    _clippy_hard(env)
    _clippy_tools(env)
    if shutil.which("cargo-deny") is None:
        _run(["cargo", "install", "cargo-deny", "--locked", "--version", "0.18.4"])
    _run(["cargo", "deny", "check", "licenses"])


def _python_sdk() -> None:
    _run(
        [
            "bazel",
            "build",
            "//core:aorta_core_cdylib",
            "//message:schemas",
            "//message:schemas_registry_manifest",
            "//message/schemas/topic/example:demo_chat_py",
            "//message/schemas/topic/example:demo_chat_schema_meta_py",
            "//rust/examples:talker",
            "//rust/examples:listener",
            "--lockfile_mode=error",
        ]
    )
    temp_root = Path(os.environ.get("RUNNER_TEMP", tempfile.gettempdir()))
    venv = temp_root / "aorta-mirror-python-venv"
    if venv.exists():
        shutil.rmtree(venv)
    _run([sys.executable, "-m", "venv", str(venv)])
    python = venv / "bin" / "python"
    _run([str(python), "-m", "pip", "install", "--quiet", "-r", "python/requirements-ci-test.txt"])
    env = os.environ.copy()
    env["AORTA_CORE_FFI_LIB"] = str(Path.cwd() / "bazel-bin/core/libaorta_core.so")
    env["PYTHON"] = str(python)
    _run([str(python), "-m", "pytest", "python/tests"], env=env)
    for script in (
        "test_scripts/python_pubsub_interop.sh",
        "test_scripts/python_rpc_interop.sh",
        "test_scripts/python_typed_examples.sh",
    ):
        _run(["bash", script], env=env)


# The pinned cargo-about 0.9.2 release used to collect third-party license
# evidence.
CARGO_ABOUT_ASSETS = {
    ("Linux", "x86_64"): (
        "cargo-about-0.9.2-x86_64-unknown-linux-musl",
        "9099a59e820c38a68b9d65f300662a567d56562f9a10f6aa4c7e86c17c2566af",
    ),
    ("Linux", "aarch64"): (
        "cargo-about-0.9.2-aarch64-unknown-linux-musl",
        "af5169282fb6f84e13471493f405437e43ac517744c9ae12fbe2cdf0a6f0e5a8",
    ),
    ("Darwin", "arm64"): (
        "cargo-about-0.9.2-aarch64-apple-darwin",
        "ae72f0df0c399a1e96336f696fa55b1b28679fd725632eba8cf8e4568467cc3e",
    ),
}


def _cargo_about_asset() -> tuple[str, str]:
    import platform

    key = (platform.system(), platform.machine())
    aliases = {("Linux", "arm64"): ("Linux", "aarch64"), ("Darwin", "aarch64"): ("Darwin", "arm64")}
    try:
        return CARGO_ABOUT_ASSETS[aliases.get(key, key)]
    except KeyError:
        raise RuntimeError(f"no pinned cargo-about for {key[0]}:{key[1]}") from None


def _prepare_cargo_about(env: dict[str, str]) -> None:
    """Install the pinned license tool into the wheel build environment.

    The wheel's Bazel action collects its own evidence. Cargo comes from the
    runner's preinstalled toolchain, as it does for the lint job.
    """
    import tarfile
    import urllib.request

    asset, digest = _cargo_about_asset()
    # One literal URL per line: the mirror's remote allowlist reads the pinned
    # release tag from it.
    url = f"https://github.com/EmbarkStudios/cargo-about/releases/download/0.9.2/{asset}.tar.gz"
    temp_root = Path(os.environ.get("RUNNER_TEMP", tempfile.gettempdir()))
    tools = temp_root / "aorta-mirror-cargo-about"
    if tools.exists():
        shutil.rmtree(tools)
    tools.mkdir(parents=True)
    archive = tools / f"{asset}.tar.gz"
    last_error: Exception | None = None
    for attempt in range(3):
        try:
            with urllib.request.urlopen(url, timeout=120) as response:
                archive.write_bytes(response.read())
            break
        except OSError as exc:  # pragma: no cover - exercised only on flaky networks
            last_error = exc
            time.sleep(5 * (attempt + 1))
    else:
        raise RuntimeError(f"failed to download {url}: {last_error}")
    actual = hashlib.sha256(archive.read_bytes()).hexdigest()
    if actual != digest:
        raise RuntimeError(f"cargo-about archive digest mismatch: {actual} != {digest}")
    with tarfile.open(archive) as tar:
        tar.extractall(tools)
    env["PATH"] = f"{tools / asset}{os.pathsep}{env['PATH']}"
    _run(["cargo", "about", "--version"], env=env)


def _python_wheels(version: str, include_messages: bool) -> None:
    env = os.environ.copy()
    _prepare_cargo_about(env)
    # Apple's Clang cannot use the release config's GCC LTO flags.
    build_flags = ["-c", "opt"] if sys.platform == "darwin" else ["--config=release"]
    targets = ["//python:aorta_sdk_wheel"]
    if include_messages:
        targets.append("//python:aorta_msgs_wheel")
    _run(
        [
            "bazel",
            "build",
            *targets,
            *build_flags,
            "--stamp",
            f"--embed_label={version}",
            "--lockfile_mode=error",
            "--action_env=HOME",
            "--action_env=CARGO_HOME",
            "--action_env=RUSTUP_HOME",
            "--action_env=RUSTUP_TOOLCHAIN",
        ],
        env=env,
    )
    # The one test that opens the wheels just built: payload ownership plus the
    # license files under .dist-info/licenses/ and the rendered notices.
    _run(
        [
            "bazel",
            "test",
            "//message/tools:python_wheel_release_test",
            *build_flags,
            "--stamp",
            f"--embed_label={version}",
            "--lockfile_mode=error",
            "--action_env=HOME",
            "--action_env=CARGO_HOME",
            "--action_env=RUSTUP_HOME",
            "--action_env=RUSTUP_TOOLCHAIN",
            "--test_output=errors",
        ],
        env=env,
    )
    dist = Path("dist")
    if dist.exists():
        shutil.rmtree(dist)
    dist.mkdir()
    wheels = sorted((Path("bazel-bin") / "python").glob("*.whl"))
    if not wheels:
        raise RuntimeError("wheel build produced no .whl files")
    for wheel in wheels:
        name = wheel.name.replace("{BUILD_EMBED_LABEL}", version)
        shutil.copy2(wheel, dist / name)


def _resolve_wheel_version(
    *,
    event_name: str,
    ref_name: str,
    input_version: str,
    stamp_path: Path = Path("MIRROR_STAMP.json"),
) -> str:
    if event_name == "push":
        if not ref_name.startswith("v") or len(ref_name) == 1:
            raise RuntimeError("wheel push must use a non-empty v* tag")
        version = ref_name[1:]
    elif event_name == "workflow_dispatch":
        if not input_version:
            raise RuntimeError("manual wheel build requires a version input")
        version = input_version
    else:
        raise RuntimeError(f"unsupported wheel event {event_name!r}")

    if stamp_path.is_file():
        stamp = json.loads(stamp_path.read_text(encoding="utf-8"))
        public_version = stamp.get("public_version")
        if public_version is not None and public_version != version:
            raise RuntimeError(
                "wheel version does not match MIRROR_STAMP.public_version: "
                f"{version!r} != {public_version!r}"
            )
    return version


def _schema_integrity() -> None:
    root = Path("message/schemas")
    document = json.loads((root / "mirror_schema_inventory.json").read_text(encoding="utf-8"))
    if set(document) != {"files"} or not isinstance(document["files"], list):
        raise RuntimeError("mirror schema inventory has invalid fields")
    expected = {
        item["path"]: item["sha256"]
        for item in document["files"]
        if isinstance(item, dict) and set(item) == {"path", "sha256"}
    }
    if len(expected) != len(document["files"]):
        raise RuntimeError("mirror schema inventory has an invalid or duplicate row")
    actual = {
        path.relative_to(root).as_posix(): hashlib.sha256(path.read_bytes()).hexdigest()
        for path in root.rglob("*.fbs")
        if path.is_file() and not path.is_symlink()
    }
    if actual != expected:
        raise RuntimeError(
            "mirror schema inventory drift: "
            f"missing={sorted(set(expected) - set(actual))}, "
            f"extra={sorted(set(actual) - set(expected))}"
        )


def _validate_mirror_checkout(root: Path) -> None:
    module = (root / "MODULE.bazel").read_text(encoding="utf-8")
    schema_shas = re.findall(r'^\s*schema_sha\s*=\s*"([^"]+)"', module, re.MULTILINE)
    if schema_shas not in ([], ["none"]):
        raise RuntimeError("mirror consumer requires MODULE.bazel schema_sha=none")

    schema_root = root / "message" / "schemas"
    inventory_path = schema_root / "mirror_schema_inventory.json"
    document = json.loads(inventory_path.read_text(encoding="utf-8"))
    if set(document) != {"files"} or not isinstance(document["files"], list):
        raise RuntimeError("mirror schema inventory has invalid fields")
    if not document["files"]:
        raise RuntimeError("mirror schema inventory is empty")

    inventory_paths = []
    for item in document["files"]:
        if not isinstance(item, dict) or set(item) != {"path", "sha256"}:
            raise RuntimeError("mirror schema inventory has an invalid row")
        relative = item["path"]
        expected = item["sha256"]
        relative_path = Path(relative) if isinstance(relative, str) else Path()
        if (
            not isinstance(relative, str)
            or not relative
            or relative_path.is_absolute()
            or ".." in relative_path.parts
            or relative_path.as_posix() != relative
            or relative_path.suffix != ".fbs"
            or not isinstance(expected, str)
            or re.fullmatch(r"[0-9a-f]{64}", expected) is None
        ):
            raise RuntimeError("mirror schema inventory has an invalid row")
        schema_file = schema_root / relative_path
        if hashlib.sha256(schema_file.read_bytes()).hexdigest() != expected:
            raise RuntimeError(f"mirror schema inventory hash mismatch for {relative}")
        inventory_paths.append(relative)

    if inventory_paths != sorted(set(inventory_paths)):
        raise RuntimeError("mirror schema inventory paths must be unique and sorted")
    actual_paths = sorted(
        path.relative_to(schema_root).as_posix()
        for path in schema_root.rglob("*.fbs")
        if path.is_file()
    )
    if actual_paths != inventory_paths:
        raise RuntimeError("mirror schema inventory does not match materialized .fbs files")


def _consumer_smoke() -> None:
    _validate_mirror_checkout(Path.cwd())
    checkout = Path.cwd()
    self_override = (
        "git_override(\n"
        '    module_name = "aorta",\n'
        f"    remote = {json.dumps(_CONSUMER_REMOTE_PLACEHOLDER)},\n"
        f"    commit = {json.dumps(_CONSUMER_COMMIT_PLACEHOLDER)},\n"
        ")\n"
    )
    with tempfile.TemporaryDirectory(prefix="aorta-mirror-consumer-") as tmp:
        root = Path(tmp)
        for relative, data in _mirror_consumer_files().items():
            destination = root / relative
            destination.parent.mkdir(parents=True, exist_ok=True)
            if relative == "MODULE.bazel":
                if self_override not in data:
                    raise RuntimeError("consumer template is missing the Aorta self override")
                data = data.replace(
                    self_override,
                    'local_path_override(\n    module_name = "aorta",\n'
                    f"    path = {json.dumps(str(checkout))},\n)\n",
                    1,
                )
            destination.write_text(data, encoding="utf-8")
        targets = [target.replace("//", "@aorta//", 1) for target in PUBLIC_BAZEL_TARGETS]
        targets.extend(
            (
                "//:flow_consumer_smoke",
                "//:baseline_consumer_smoke_cxx17",
                "//:baseline_consumer_smoke_noexcept",
                "//:sdk_consumer_smoke",
                "//:micro_ping_cc",
                "//:map_upload_action_cc",
                "//:aorta_rules_rust_patch_label",
            )
        )
        startup = [f"--output_user_root={root / 'bazel-output'}"]
        common = ["--lockfile_mode=update", "--experimental_convenience_symlinks=ignore"]
        _run(
            [
                "bazel",
                *startup,
                "build",
                *targets,
                *common,
            ],
            cwd=root,
        )
        _run(["bazel", *startup, "test", "//:consumer_test", *common], cwd=root)


def _preflight() -> None:
    env = dict(os.environ, RUSTUP_TOOLCHAIN=RUST_TOOLCHAIN)
    for mode in ("lint", "consumer-smoke", "build-test"):
        _run(["python3", ".github/scripts/mirror_ci.py", mode], env=env)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    subparsers = parser.add_subparsers(dest="command", required=True)
    for command in ("build-test", "consumer-smoke", "lint", "clippy-hard", "clippy-tools", "python-sdk", "schema-integrity", "preflight"):
        subparsers.add_parser(command)
    wheels = subparsers.add_parser("python-wheels")
    wheels.add_argument("--event-name", required=True)
    wheels.add_argument("--ref-name", required=True)
    wheels.add_argument("--version-input", default="")
    wheels.add_argument("--include-messages", choices=("true", "false"), required=True)
    args = parser.parse_args(argv)

    actions = {
        "build-test": _build_test,
        "consumer-smoke": _consumer_smoke,
        "lint": _lint,
        "clippy-hard": _clippy_hard,
        "clippy-tools": _clippy_tools,
        "python-sdk": _python_sdk,
        "schema-integrity": _schema_integrity,
        "preflight": _preflight,
    }
    if args.command == "python-wheels":
        version = _resolve_wheel_version(
            event_name=args.event_name,
            ref_name=args.ref_name,
            input_version=args.version_input,
        )
        _python_wheels(version, args.include_messages == "true")
    else:
        return actions[args.command]() or 0
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
